.pswp.pswp--animate_opacity {
  transition: opacity 0.4s cubic-bezier(0.4, 0, 0.22, 1);
}

.pswp .pswp__zoom-wrap {
  transition: transform 0.4s cubic-bezier(0.75, 0, 0.175, 1);
}

.pswp .pswp__bg {
  transition: opacity 0.4s cubic-bezier(0.4, 0, 0.22, 1);
