/*====== Cart Quantity ======*/
.cart__item__quantity {
  position: relative;
  width: 80px;
  transition: opacity 0.4s;
}
.cart__item__quantity.read-only {
  opacity: 0.5;
  pointer-events: none;
}
.cart__item__quantity button {
  position: absolute;
  top: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 100%;
  font-size: 0;
  line-height: 1;
  border-radius: 0;
  transform: translateY(-50%);
  transition: color 0.3s;
  color: var(--text-alpha-50);
}
.cart__item__quantity button.is-disabled {
  pointer-events: none;
  opacity: 0.5;
}
.cart__item__quantity button:hover {
  color: var(--text);
}
.cart__item__quantity .icon {
  width: 8px;
  height: 8px;
}
.cart__item__quantity input[type=number] {
  -moz-appearance: textfield;
}
.cart__item__quantity input[type=number]::-webkit-outer-spin-button,
.cart__item__quantity input[type=number]::-webkit-inner-spin-button {
  -webkit-appearance: none;
}

.cart__item__quantity-minus {
  left: 0;
  box-shadow: var(--BORDER-WIDTH) 0 var(--COLOR-BORDER-ALPHA-50);
}

.cart__item__quantity-plus {
  right: 0;
  box-shadow: calc(var(--BORDER-WIDTH) * -1) 0 var(--COLOR-BORDER-ALPHA-50);
}

.cart__item__quantity-field {
  display: flex;
  width: 100%;
  padding: 6px 20px;
  border: var(--BORDER-WIDTH) solid var(--COLOR-BORDER-ALPHA-50);
  border-radius: 1px;
  margin: 0;
  font-size: calc(0.75rem * var(--adjust-body));
  line-height: normal;
  color: inherit;
  text-align: center;
}

/*====== Cart Quantity ======*/
.cart__discount {
  width: 100%;
  padding: 5px 15px;
  border-radius: 3px;
  margin: var(--inner) 0 0;
  background-color: var(--PRIMARY-BUTTONS-COLOR-ALPHA-50);
  font-size: calc(0.75rem * var(--adjust-body));
  color: var(--PRIMARY-BUTTONS-COLOR-TEXT);
}
.cart__discount .icon-tags {
  display: inline-block;
  vertical-align: middle;
  width: 12px;
  height: 12px;
  margin-right: 4px;
  stroke: currentcolor;
  stroke-width: 1px;
}

/*====== Cart Errors ======*/
.cart__errors {
  position: relative;
  width: 100%;
  visibility: hidden;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition: opacity 0.5s ease, max-height 0.5s cubic-bezier(0, 1, 0.5, 1), visibility 0.5s;
}
.cart__errors.is-expanded {
  opacity: 1;
  visibility: visible;
  max-height: 300px;
  transition-timing-function: cubic-bezier(0, 0, 1, 0);
}

.cart__errors__inner {
  position: relative;
  padding: calc(var(--inner) * 0.75) calc(var(--inner) * 2) calc(var(--inner) * 0.75) var(--inner);
  border: var(--BORDER-WIDTH) solid var(--error);
  border-radius: var(--RADIUS-CHECKBOX);
  margin: 0 auto calc(var(--inner) * 0.75);
  background-color: var(--error-bg);
}
@media only screen and (max-width: 767px) {
  .cart__errors__inner {
    padding: calc(var(--inner) / 2) calc(var(--inner) * 2) calc(var(--inner) / 2) var(--gutter-mobile);
  }
}

.cart__errors__close,
.errors__button-close {
  position: absolute;
  top: 50%;
  right: 10px;
  width: 32px;
  height: 32px;
  padding: 8px;
  transform: translateY(-50%);
}
.cart__errors__close .icon,
.errors__button-close .icon {
  display: block;
  width: 100%;
  height: 100%;
  transition: transform 0.3s ease;
}
.cart__errors__close:hover .icon,
.errors__button-close:hover .icon {
  transform: rotate(90deg);
}

.cart__errors__heading {
  margin: 0;
  font-size: calc(0.75rem * var(--adjust-body));
  color: var(--error);
}

.cart__errors__content {
  width: 100%;
  margin: 0;
  font-size: calc(0.75rem * var(--adjust-body));
  color: var(--error);
}

.cart-drawer__errors {
  position: sticky;
  top: 0;
  z-index: 9;
  background: var(--bg);
}
.cart-drawer__errors .cart__errors__inner {
  padding: 10px 40px 10px 20px;
  margin: calc(var(--inner) / 2) 0 0;
  border-radius: 0;
  border-left: none;
  border-right: none;
}

/*====== Cart Loader ======*/
.is-loading .cart__item__quantity,
.is-disabled .cart__item__quantity {
  pointer-events: none;
  opacity: 0.6;
}

/*====== Cart Message ======*/
.cart__message {
  display: flex;
  flex-flow: row nowrap;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  margin: 0;
  padding: var(--inner);
  font-size: calc(0.815rem * var(--adjust-body));
  transition: max-height 0.3s, padding 0.3s, border 0.3s, opacity 0.3s, visibility 0.3s;
}

.cart__message__success,
.cart__message__default {
  padding-bottom: 6px;
}

.cart__message__success {
  display: none;
}

.is-success .cart__message__success {
  display: inline;
}

.is-success .cart__message__success ~ .cart__message__default {
  display: none;
}

.cart__message.is-hidden,
.cart__message__default.is-hidden {
  overflow: hidden;
  visibility: hidden;
  max-height: 0;
  padding: 0 15px;
  border: none;
  opacity: 0;
}

/*====== Cart terms ======*/
.cart__buttons-wrapper {
  display: flex;
  flex-flow: row wrap;
  width: 100%;
}

.cart__acceptance__input {
  display: block;
  width: 13px;
  height: 13px;
  margin: calc(4px * var(--adjust-body)) 7px 5px 0;
  float: none;
}

.cart__acceptance__label {
  display: block;
  cursor: pointer;
  width: calc(100% - 25px);
  font-size: calc(0.815rem * var(--adjust-body));
}
.cart__acceptance__label p {
  margin: 0;
  font-size: inherit;
}

.cart__buttons__fieldset {
  padding: 0;
  margin: 0;
  border: none;
}

.cart__buttons {
  width: 100%;
}

.cart__buttons--disabled {
  position: relative;
}

.cart__buttons--disabled:after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  cursor: default;
  background: var(--bg-alpha-35);
  z-index: 1;
  cursor: default;
  transition: opacity 0.3s ease, visibility 0s linear 0s;
}

.cart__acceptance__input ~ .cart__buttons {
  margin-top: var(--inner);
}

.cart__acceptance__input:checked ~ .cart__buttons--disabled:after {
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0s linear 0.3s;
}

.cart__terms {
  width: 100%;
  margin: 0;
  font-size: calc(0.75rem * var(--adjust-body));
  color: var(--error);
  visibility: hidden;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition: opacity 0.5s ease, margin 0.5s ease, max-height 0.5s cubic-bezier(0, 1, 0.5, 1), visibility 0.5s;
}
.cart__terms.is-expanded {
  opacity: 1;
  visibility: visible;
  max-height: 300px;
  margin-top: var(--inner);
  transition: opacity 0.5s ease, margin 0.5s ease, max-height 0.5s cubic-bezier(0, 0, 1, 0), visibility 0.5s;
}

.cart__message__progress__holder {
  display: block;
  width: 100%;
}

.cart__message__progress {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  border: none;
  width: 100%;
  height: 7px;
  border-radius: 6px;
  background-color: var(--text-alpha-10);
  color: var(--PRIMARY-BUTTONS-COLOR-BG);
}

.cart__message__progress:nth-child(2) {
  display: none;
}

/* WEBKIT BROWSERS - CHROME, OPERA AND SAFARI */
.cart__message__progress::-webkit-progress-bar {
  background-color: transparent;
  border-radius: 6px;
}

.cart__message__progress::-webkit-progress-value {
  background-color: var(--accent);
  border-radius: 6px;
}

.aos-initialized .cart__message__progress::-webkit-progress-value {
  width: 0 !important;
  -webkit-transition: width 1s ease 0s;
  transition: width 1s ease 0s;
}

.aos-initialized .cart .cart__message__progress::-webkit-progress-value,
.aos-initialized .cart-drawer__message.aos-animate .cart__message__progress::-webkit-progress-value {
  width: min(var(--progress-width, 100%), 100%) !important;
  transition-delay: 0.5s;
}

/* MOZILLA FIREFOX */
.cart__message__progress::-moz-progress-bar {
  background-color: var(--accent);
  border-radius: 6px;
}

@-moz-document url-prefix() {
  .aos-initialized .cart__message__progress:first-child:not(:last-child) {
    display: none;
  }
  .aos-initialized .cart__message__progress:nth-child(2) {
    display: block;
  }
  .aos-initialized .cart__message__progress:indeterminate::-moz-progress-bar {
    width: 0 !important;
    -moz-transition: width 1s ease-in-out 0s;
    transition: width 1s ease-in-out 0s;
  }
  .aos-initialized .cart .cart__message__progress:indeterminate::-moz-progress-bar,
  .aos-initialized .cart-drawer__message.aos-animate .cart__message__progress:indeterminate::-moz-progress-bar {
    width: min(var(--progress-width, 100%), 100%) !important;
    transition-delay: 0.5s;
  }
}
/*====== Cart Message Custom ======*/
.cart__message--custom {
  text-align: center;
  background: var(--accent);
}
.cart__message--custom p {
  margin: 0 auto;
}

/*====== Pair Product ======*/
.cart__pair {
  border-top: var(--BORDER-WIDTH) solid var(--text);
  padding-top: 10px;
  margin-bottom: 30px;
  transition: opacity 0.3s;
}
.cart__pair.fade-out {
  opacity: 0;
}
.cart__pair .flickity-page-dots {
  position: static;
  margin: 9px 0 -25px;
}

.cart__pair:empty {
  display: none;
}

#dynamic-checkout-cart:empty {
  min-height: 0 !important;
}

/*================ Circle Text ================*/
.circle-text__content {
  width: var(--circle-size);
}
@media only screen and (max-width: 767px) {
  .circle-text__content {
    max-width: 125px;
    max-height: 125px;
  }
}

.circle-text__content img {
  display: block;
  max-width: var(--circle-size);
  height: auto;
  margin: 0 auto;
}
@media only screen and (max-width: 767px) {
  .circle-text__content img {
    width: auto;
    max-width: 125px;
    max-height: 125px;
  }
}

.circle-text__content svg {
  font-family: var(--FONT-STACK-HEADING);
  font-weight: var(--FONT-WEIGHT-HEADING);
  font-style: var(--FONT-STYLE-HEADING);
  text-transform: var(--HEADING-TEXT-CAPS);
  display: block;
  width: var(--circle-size);
  height: var(--circle-size);
  color: var(--circle-color);
  word-spacing: var(--circle-word-spacing);
}
@media only screen and (max-width: 767px) {
  .circle-text__content svg {
    max-width: 125px;
    max-height: 125px;
  }
}

.circle-text {
  transform: rotate(var(--rotate, 0deg));
}
@media only screen and (max-width: 767px) {
  .circle-text {
    transition: transform 0.1s linear;
  }
}
.circle-text.is-rotating {
  animation: rotate 20s infinite linear;
  animation-direction: reverse;
}
@media only screen and (max-width: 767px) {
  .circle-text.is-rotating {
    transition: none;
  }
}
.circle-text.is-static-text {
  --rotate: 75deg;
}

/*=============== Section Columns ===============*/
.section-columns {
  display: flex;
  justify-content: center;
  overflow: hidden;
  color: var(--text);
  background-color: var(--bg);
}

.section-columns__wrapper,
.section-columns__slider .flickity-viewport {
  overflow: initial;
}

.section-columns__slider .flickity-button {
  background: var(--bg);
}

@media only screen and (max-width: 767px) {
  .section-columns__wrapper .grid--mobile,
  .section-columns__wrapper .stacked--mobile {
    row-gap: calc(var(--gutter) / 2);
  }
}

@media only screen and (max-width: 767px) {
  .stacked--mobile .column-item {
    width: var(--wrapper-width);
  }
}
.column-item:first-child:last-child {
  display: block;
}
@media only screen and (min-width: 768px) {
  .column-item:first-child:last-child {
    width: calc(var(--wrapper-width) / 2);
    margin: 0 auto;
  }
}
@media only screen and (max-width: 767px) {
  .column-item:first-child:last-child {
    margin: 0;
  }
}

.column-item--border {
  display: flex;
  flex-flow: column;
  justify-content: center;
  position: relative;
}
.carousel--resize .column-item--border {
  min-height: 100%;
}
.column-item--border:after {
  position: absolute;
  top: 0;
  bottom: 0;
  right: calc(-1 * var(--grid-gutter) / 2);
  width: var(--BORDER-WIDTH);
  background: var(--border);
  content: "";
}
.column-item--border[data-aos]:after {
  opacity: 0;
  top: 25%;
  bottom: 25%;
  transition: opacity 0.6s ease 0.15s, top 0.6s ease 0.15s, bottom 0.6s ease 0.15s;
}
.no-js .column-item--border:after, .column-item--border.aos-animate:after {
  opacity: 1;
  top: 0;
  bottom: 0;
}
.column-item--border:last-child:after {
  display: none;
}
.column-item--border .column-item__inner {
  padding: 10px 0;
}
@media only screen and (max-width: 767px) {
  .section-columns__slider .column-item--border {
    display: flex;
  }
  .stacked--mobile .column-item--border:after {
    top: auto;
    bottom: calc(-1 * var(--gutter) / 4);
    left: 25%;
    right: 25%;
    width: auto;
    height: var(--BORDER-WIDTH);
  }
  .stacked--mobile .column-item--border[data-aos]:after {
    left: 0;
    right: 0;
  }
  .stacked--mobile .column-item--border.aos-animate:after {
    left: 25%;
    right: 25%;
  }
  .stacked--mobile .column-item--border.column-item--image {
    margin-bottom: calc(var(--gutter) / 2);
  }
  .stacked--mobile .column-item--border.column-item--image:after {
    bottom: calc(-1 * var(--gutter) / 2);
  }
  .carousel--resize.stacked--mobile .column-item--border.column-item--image:after {
    bottom: 0;
  }
}
@media only screen and (min-width: 480px) and (max-width: 767px) {
  .grid--mobile .column-item--border:nth-child(3n):after {
    display: none;
  }
}
@media only screen and (max-width: 479px) {
  .grid--mobile .column-item--border:nth-child(2n):after {
    display: none;
  }
}

.column-item--image {
  justify-content: flex-start;
}
.column-item--image .column-item__inner {
  padding: 0;
}
.column-item--image .column-item__content:empty {
  display: none;
}
.column-item--image:has(.column-item__content:empty) .column-item__image-wrapper {
  margin-bottom: 0;
}

.column-item__image-wrapper {
  margin-bottom: calc(var(--gutter) / 2);
  position: relative;
  overflow: hidden;
}

.column-item__image {
  display: block;
  height: auto;
  position: relative;
  overflow: hidden;
  padding-top: var(--aspect-ratio);
  background-color: var(--bg);
}
.column-item__image img,
.column-item__image .placeholder-svg-filled {
  position: absolute;
  top: 0;
  left: 0;
}

.column-item__video-link .play-button {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  opacity: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.column-item__content {
  overflow-wrap: break-word;
  width: 100%;
}
.column-item__content p {
  margin: 0;
}
.column-item__content h3 {
  margin-bottom: 0.25em;
}
.text-left .column-item__content {
  text-align: left;
}

/* Multicolumn */
@media only screen and (min-width: 768px) {
  .section-columns--multicolumn .section-columns__wrapper {
    margin: 0;
  }
}
@media only screen and (min-width: 768px) {
  .section-columns--multicolumn .section-columns__slider {
    display: flex;
    flex-flow: row wrap;
    padding: 0;
    margin: calc(-1 * var(--grid-gutter) / 2);
  }
}
@media only screen and (min-width: 768px) {
  .section-columns--multicolumn .column-item {
    width: var(--desktop-width);
    padding: calc(var(--grid-gutter) / 2);
    margin: 0;
  }
}
.section-columns--multicolumn .column-item__inner {
  height: 100%;
}
.section-columns--multicolumn .column-item__image-wrapper {
  margin-bottom: var(--inner);
  --aspect-ratio: var(--image-ratio-desktop);
}
@media only screen and (max-width: 767px) {
  .section-columns--multicolumn .column-item__image-wrapper {
    margin-bottom: var(--inner-mobile);
    --aspect-ratio: var(--image-ratio-mobile);
  }
}
.section-columns--multicolumn .column-item__image-link {
  display: block;
}
@media only screen and (max-width: 767px) {
  .section-columns--multicolumn .grid--mobile .mobile--one-half {
    width: 100%;
  }
}
.section-columns--multicolumn .column-item__button {
  margin-top: calc(var(--inner) / 2);
  vertical-align: top;
}
.section-columns--multicolumn .column-item__button:only-child {
  margin-top: 0;
}
@media only screen and (max-width: 767px) {
  .section-columns--multicolumn .grid--mobile,
  .section-columns--multicolumn .stacked--mobile {
    row-gap: var(--grid-gutter);
  }
}

.column-item--menu .column-item__inner {
  display: flex;
  flex-flow: row wrap;
  align-items: center;
}
.column-item--menu .column-item__links {
  width: 100%;
  padding: var(--inner);
}
@media only screen and (max-width: 767px) {
  .stacked--mobile .column-item--menu .column-item__links, .grid--mobile .column-item--menu .column-item__links {
    padding: 0;
  }
}

.column-item--text .column-item__inner {
  height: 100%;
  display: flex;
  flex-flow: row wrap;
  align-items: center;
}
.column-item--text .column-item__content {
  width: 100%;
}
.column-item--text .column-item__content p {
  margin-bottom: calc(var(--inner) / 2);
}
.column-item--text .column-item__content h3 {
  margin-bottom: var(--inner);
}

.column-item--boxed .column-item__inner {
  background: var(--bg);
}
.column-item--boxed .column-item__content {
  padding: var(--inner);
}
@media only screen and (max-width: 767px) {
  .column-item--boxed .column-item__content {
    padding: calc(var(--inner-mobile) * 2) var(--inner-mobile);
  }
}

/*================ Collection ================*/
:root {
  --product-media-padding-top: var(--PRODUCT-MEDIA-PADDING-TOP);
}

.template-collection .collection-section {
  background: var(--bg);
}

.collection-section {
  --swatch-size: 30px;
  position: relative;
}
@media only screen and (min-width: 768px) {
  .collection-section {
    --swatch-size: 24px;
  }
}
.collection-section .swatch__button .icon-check {
  width: 14px;
  margin-right: 0;
}
.collection-section .pagination {
  margin-bottom: 0;
}

.collection__wrapper {
  position: relative;
  transition: height 0.3s ease;
  min-height: var(--content-min);
}

.collection__header {
  position: relative;
  overflow: initial;
  z-index: 10;
}

.collection__title {
  --heading-size: calc(3rem * var(--adjust-heading));
  font-size: var(--heading-size);
  line-height: 1.2;
  margin-bottom: 10px;
}
@media only screen and (max-width: 1439px) {
  .collection__title {
    --heading-size: calc(2.5rem * var(--adjust-heading));
  }
}
@media only screen and (max-width: 767px) {
  .collection__title {
    --heading-size: calc(2.25rem * var(--adjust-heading));
  }
}

.collection__description {
  margin: 20px auto 0;
  display: block;
  color: inherit;
  --text-size: calc(1.1rem * var(--adjust-body));
  font-size: var(--text-size);
}
@media only screen and (max-width: 767px) {
  .collection__description {
    --text-size: calc(1rem * var(--adjust-body));
  }
}
.collection__description p {
  font-size: inherit;
}

.collection__inner {
  display: flex;
  flex-flow: row wrap;
  width: var(--wrapper-width);
}
.collection__inner .breadcrumbs {
  margin: 20px 0;
  flex-basis: 100%;
  width: 100%;
  font-size: var(--text-size);
}
@media only screen and (min-width: 768px) {
  .collection__inner .breadcrumbs {
    flex-basis: 240px;
  }
}
@media only screen and (min-width: 1024px) {
  .collection__inner .breadcrumbs {
    margin-right: calc(var(--gutter) / 2);
  }
}
@media only screen and (min-width: 1440px) {
  .collection__inner .breadcrumbs {
    flex-basis: 300px;
  }
}
.collection__inner:after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 100%;
  z-index: 5;
  opacity: 0;
  visibility: hidden;
  background: var(--bg-overlay) var(--loading-svg) no-repeat center center/320px;
  transition: opacity 0.3s ease, visibility 0s linear 0.3s;
}
.palette--dark .collection__inner:after {
  filter: invert(1);
}
.search-page.is-loading .collection__inner:after, .collection.is-loading .collection__inner:after {
  opacity: 1;
  visibility: visible;
  transition-delay: 0s;
}

.collection--filters-disabled .collection__inner .breadcrumbs {
  grid-column: 1/3;
}
@media only screen and (min-width: 768px) {
  .collection--filters-disabled .collection__inner .breadcrumbs {
    margin-bottom: 0;
  }
}

.collection__products-count {
  justify-self: flex-end;
  flex-grow: 1;
  text-align: right;
  font-size: var(--text-size);
}
@media only screen and (max-width: 767px) {
  .collection__products-count {
    display: none;
  }
}

.collection__products {
  overflow: hidden;
  width: 100%;
  position: relative;
  z-index: 0;
}
.collection__products .no-matches {
