/*================ Contact form section ================*/
.contact-form__message {
  position: fixed;
  width: 100%;
  bottom: 0;
  left: 0;
  z-index: 8995;
  background: var(--bg);
  box-shadow: 0 -5px 5px 0 rgba(0, 0, 0, 0.05);
