  transition: transform 0.45s ease, visibility 0s;
  max-height: 50vh;
  overflow-x: hidden;
  overflow-y: auto;
}
.contact-form__message.hide-down {
  transform: translateY(100%);
  visibility: hidden;
  transition-delay: 0s, 0.45s;
}
.contact-form__message .errors,
