.product__notification label {
  display: block;
  font-size: calc(0.875rem * var(--adjust-body));
  margin-bottom: 15px;
}
.product__notification .input-group {
  max-width: 100%;
  flex-direction: column;
}
.product__notification .input-group__item {
  max-width: 100%;
}
.product__notification .input-group__field {
  border: var(--BORDER-WIDTH) solid var(--border);
  border-radius: var(--RADIUS);
}
.product__notification .input-group__item--btn {
  margin-top: var(--form-top);
  flex: 1;
  max-width: 100%;
  width: 100%;
}
.product__notification button[type=submit] {
  width: 100%;
}
@media only screen and (max-width: 767px) {
  .product__notification {
    padding: var(--gutter-mobile);
  }
}
.product__notification .contact-form {
  margin-top: 16px;
}

.product__notification__title {
  font-size: calc(2rem * var(--adjust-heading));
  margin-bottom: 0;
}
@media only screen and (max-width: 767px) {
  .product__notification__title {
    padding: 0 var(--inner-mobile);
  }
}

.product__notification__subtitle {
  font-size: calc(1rem * var(--adjust-body));
  margin: 5px 0 0;
}

.product__notification__close {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 30px;
  height: 30px;
  padding: 5px;
  opacity: 1;
  text-indent: 0;
  color: inherit;
  background: none;
}
.product__notification__close:hover .icon-close {
  transform: rotate(90deg);
}
@media only screen and (max-width: 767px) {
  .product__notification__close {
    top: 10px;
    right: 10px;
    width: 25px;
    height: 25px;
  }
}

.product__notification__message {
  display: none;
  margin: var(--gutter) 0;
  text-align: center;
}

.template-product .pswp--success .product__notification__form {
  display: none;
}
.template-product .pswp--success .product__notification__message {
  display: block;
}

/*
* Quantity
*/
.quantity__selector {
  display: block;
  width: 100%;
  padding: var(--form-top) 32px;
  font-size: calc(0.875rem * var(--adjust-body));
  text-align: center;
  letter-spacing: 0.02em;
  line-height: 1.3;
}
.quantity__selector input[type=number]::-webkit-outer-spin-button,
.quantity__selector input[type=number]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
.quantity__selector input[type=number] {
  -moz-appearance: textfield;
}

.quantity__btn {
  height: 50%;
  width: 44px;
  color: inherit;
}

.quantity__btn--decrease,
.quantity__btn--increase {
  position: absolute;
  top: 0;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.quantity__btn--decrease {
  left: 0;
}

.quantity__btn--increase {
  right: 0;
}

.product__form {
  --form-top: 10px;
  display: grid;
  grid-template-columns: minmax(0, 100%);
  gap: var(--grid-gutter);
  position: relative;
}
@media only screen and (max-width: 767px) {
  .product__form {
    --form-margin: var(--form-margin-mobile);
    gap: calc(var(--form-margin) * 2);
  }
  .variant__labels--hide .product__form {
    gap: var(--form-margin);
  }
}
.product__form .btn--submit {
  position: relative;
  width: 100%;
  transition: color 0.3s ease, border 0.3s ease, background 0.3s linear;
}
.product__form .btn--submit span {
  transition: opacity 0.3s ease;
}
.product__form .btn--submit.is-loading {
  opacity: 1;
  cursor: default;
}
.product__form .btn--submit.is-loading span {
  opacity: 0;
  transition: opacity 0s;
}
.product__form .btn--submit.is-loading:before {
  content: none;
}
.product__form .btn--submit .loader-indeterminate {
  background-color: var(--btn-text);
}
.product__form .btn--submit .loader--line {
  transition: opacity 0.3s ease, visibility 0s linear 0s;
  background-color: var(--btn-text-alpha-10);
}
.product__form .btn, .product__form .shopify-payment-button__button--unbranded,
.product__form .shopify-payment-button {
  width: 100%;
}
.product__form .errors {
  margin-bottom: 0;
}

.product__form__select {
  display: none;
}

.shop-pay-terms {
  font-size: calc(0.875rem * var(--adjust-body));
}

.shop-pay-terms:empty {
  display: none;
}

/*
* Submit buttons
*/
.product__submit__holder--spb .shopify-payment-button__button--unbranded {
  border: var(--BORDER-WIDTH) solid transparent;
  padding: var(--form-top) var(--form-left);
}
.product__submit__holder--spb .product__submit__add {
  min-height: 44px;
}

.shopify-payment-button__more-options {
  font-size: calc(0.85rem * var(--adjust-body)) !important;
  margin-top: 5px !important;
}

.product__submit__buttons {
  --form-margin: 12px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--form-margin);
}
@media only screen and (max-width: 767px) {
  .product__submit__buttons {
    --form-margin: var(--form-margin-mobile);
  }
}
@media only screen and (min-width: 1024px) {
  .btn--half .product__submit__buttons {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .btn--half.variant--soldout .product__submit__holder--notification .product__submit__buttons {
    grid-template-columns: minmax(0, 1fr);
  }
}
.product__submit__buttons .shopify-payment-button__button--hidden {
  display: none;
}

.product__submit__add em {
  font-style: normal;
}
.product__submit__add .product__price--regular {
  margin: 0;
}
.product__submit__add .product__price--regular:before {
  content: "•";
  margin: 0 5px;
}

.product__submit__item .loader--line {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 80%;
  margin: auto;
}

/*
* Form errors
*/
.product__form__errors {
  overflow: hidden;
  position: relative;
  text-align: left;
  max-height: 0;
  visibility: hidden;
  opacity: 0;
  transition: max-height 0.3s, visibility 0.3s, opacity 0.3s, margin 0.3s;
}
.product__form__errors.is-visible {
  max-height: 500px;
  visibility: visible;
  opacity: 1;
  transition: max-height 0.3s 0.3s, visibility 0.3s 0.3s, opacity 0.3s 0.3s, margin 0.3s 0.3s;
}
@media only screen and (max-width: 479px) {
  .product__form__errors {
    max-width: 390px;
  }
}
.product__form__errors .errors {
  max-width: 100%;
  margin: var(--form-margin) 0;
  padding: 15px 40px 15px 15px;
  position: relative;
}
@media only screen and (max-width: 767px) {
  .product__form__errors .errors {
    --form-margin: var(--form-margin-mobile);
  }
}
.product__form__errors .errors__close {
  position: absolute;
  top: 0;
  right: 0;
  width: 32px;
  height: 32px;
  padding: 5px;
  z-index: 20;
  cursor: pointer;
}
.product__form__errors .errors__close .icon-close {
  width: 100%;
  height: 100%;
}
.product__form__errors .errors__close:hover .icon-close {
  transform: rotate(90deg);
}

/*
* Form success
*/
.product__add__success {
  display: flex;
  align-items: stretch;
  background: var(--bg);
  border-left: var(--BORDER-WIDTH) solid var(--border);
  border-bottom: var(--BORDER-WIDTH) solid var(--border);
}
@media only screen and (max-width: 767px) {
  .product__add__success {
    border-left: none;
  }
}

.product__add__success__image {
  width: 50%;
}
@media only screen and (max-width: 767px) {
  .product__add__success__image {
    display: none;
  }
}

.product__add__success__image-bg {
  height: 100%;
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
}

.product__add__success__content {
  width: 50%;
  padding: 50px;
}
@media only screen and (max-width: 767px) {
  .product__add__success__content {
    width: 100%;
    padding: 15px 20px;
  }
}

.product__add__success--hide {
  display: none;
}

/*
* Variant States
*/
.variant--soldout .quantity-selector label,
.variant--soldout .quantity-selector input,
.variant--soldout .quantity-selector button,
.variant--soldout .shopify-payment-button label,
.variant--soldout .shopify-payment-button input,
.variant--soldout .shopify-payment-button button,
.variant--soldout .product__price label,
.variant--soldout .product__price input,
.variant--soldout .product__price button,
.variant--unavailabe .quantity-selector label,
.variant--unavailabe .quantity-selector input,
.variant--unavailabe .quantity-selector button,
.variant--unavailabe .shopify-payment-button label,
.variant--unavailabe .shopify-payment-button input,
.variant--unavailabe .shopify-payment-button button,
.variant--unavailabe .product__price label,
.variant--unavailabe .product__price input,
.variant--unavailabe .product__price button {
  cursor: default;
}
.variant--soldout .product__submit__add,
.variant--soldout .product__submit__add:hover,
.variant--unavailabe .product__submit__add,
.variant--unavailabe .product__submit__add:hover {
  border-color: transparent;
  background-color: var(--text-alpha-10);
  color: var(--text-alpha-50);
  cursor: not-allowed;
}
.variant--soldout .product__submit__add > *,
.variant--soldout .product__submit__add:hover > *,
.variant--unavailabe .product__submit__add > *,
.variant--unavailabe .product__submit__add:hover > * {
  pointer-events: none;
}
@media only screen and (max-width: 767px) {
  .variant--soldout .product__submit__add,
  .variant--soldout .product__submit__add:hover,
  .variant--unavailabe .product__submit__add,
  .variant--unavailabe .product__submit__add:hover {
    transform: none;
    pointer-events: none;
  }
}
.variant--soldout .product__submit__add:before,
.variant--unavailabe .product__submit__add:before {
  background-color: var(--text-alpha-25);
}
.variant--soldout .shopify-payment-button,
.variant--unavailabe .shopify-payment-button {
  position: relative;
  pointer-events: none;
}
.variant--soldout .shopify-payment-button:after,
.variant--unavailabe .shopify-payment-button:after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0);
  z-index: 2;
}

.variant--soldout .product__submit__holder--notification .product__submit__add,
.variant--soldout .product__submit__holder--notification .product__submit__add:hover {
  cursor: pointer;
  pointer-events: auto;
}

.variant--unavailabe .product__price {
  opacity: 0;
}

/*================ Product Upsell ================*/
.body--rounded-corners .upsell__products {
  overflow: initial;
}
.upsell__products .flickity-page-dots {
  --text: var(--COLOR-TEXT);
  bottom: -28px;
}

.upsell__products--slider {
  padding-bottom: max(54px, var(--padding-bottom));
}

.product-upsell__holder {
  --heading: var(--upsells-text);
  --text-lighten: var(--upsells-text-lighten);
  --disabled-grey-darken: var(--upsells-disabled-grey-darken);
  --inner: 12px;
  --border-color: var(--upsells-border, transparent);
  border: var(--BORDER-WIDTH) solid var(--border-color);
  padding: var(--inner);
  width: 100%;
  background-color: var(--upsells-bg);
  color: var(--upsells-text);
  transition: opacity 0.3s;
}
.product-upsell__holder.fade-out {
  opacity: 0;
}
.flickity-slider .product-upsell__holder {
  margin-right: var(--inner);
}

.product-upsell__holder__title {
  font-weight: var(--FONT-WEIGHT-HEADING);
  --heading-size: calc(1rem * var(--adjust-heading));
  font-size: var(--heading-size);
}
@media only screen and (max-width: 767px) {
  .product-upsell__holder__title {
    --heading-size: calc(0.875rem * var(--adjust-heading));
  }
}

.product-upsell {
  min-height: calc(var(--UPSELLS-HEIGHT) - 2 * (var(--inner) + var(--BORDER-WIDTH)));
  position: relative;
  display: flex;
  justify-content: flex-start;
}

.product-upsell__content {
  position: relative;
  z-index: 2;
  flex: 0 0 calc(100% - var(--UPSELLS-IMAGE-WIDTH));
  max-width: calc(100% - var(--UPSELLS-IMAGE-WIDTH));
  padding: 5px 0 5px var(--inner);
  font-size: calc(1rem * var(--adjust-body));
  display: flex;
  flex-flow: column wrap;
}
.product-upsell__content .shopify-product-form {
  margin-top: auto;
}

.product-upsell__image {
  position: relative;
  max-width: var(--UPSELLS-IMAGE-WIDTH);
  flex: 0 0 var(--UPSELLS-IMAGE-WIDTH);
  display: block;
  background-color: var(--upsells-bg);
  filter: var(--product-filter-bg);
  overflow: hidden;
}

.product-upsell__title {
  font-family: var(--FONT-STACK-HEADING);
  font-weight: var(--FONT-WEIGHT-HEADING);
  font-style: var(--FONT-STYLE-HEADING);
  text-transform: var(--HEADING-TEXT-CAPS);
  font-size: calc(1rem * var(--adjust-heading));
  margin: 0 10px 10px 0;
}

.product-upsell__subtitle {
  margin: 0 0 10px;
  font-size: calc(0.75rem * var(--adjust-body));
}

.product-upsell__row {
  display: flex;
  flex-flow: row wrap;
  justify-content: space-between;
  align-items: center;
}

.product-upsell__variant-title {
  color: var(--text-lighten);
  font-size: calc(0.8rem * var(--adjust-body));
  margin: 0;
}

.product-upsell__variant-title span {
  display: inline-block;
  width: 2px;
  height: 2px;
  border-radius: 50%;
  margin: 0 4px;
  background-color: currentcolor;
  vertical-align: middle;
  opacity: 0.8;
}

.product-upsell__price {
  margin: 0 0 10px;
  font-size: calc(0.75rem * var(--adjust-body));
}

.product-upsell__price-new {
  margin-right: 5px;
}
.product-upsell__price-new:last-child {
  margin-right: 0;
}

.product-upsell__unit-price {
  --text-size: calc(0.75rem * var(--adjust-body));
  font-size: var(--text-size);
  line-height: calc(1.171875 * var(--adjust-body));
  opacity: 0.5;
}

.product-upsell__btn {
  font-size: calc(0.875rem * var(--adjust-button));
  min-width: 0;
  margin-top: auto;
  align-self: flex-start;
}
@media only screen and (max-width: 479px) {
  .product-upsell__btn {
    width: auto;
  }
}
.product-upsell__btn.btn--small {
  --top-bottom-padding: 6px;
  --left-right-padding: 20px;
}
.product-upsell__btn.btn--medium {
  --top-bottom-padding: 9px;
  --left-right-padding: 26px;
}
.product-upsell__btn.btn--large {
  --top-bottom-padding: 12px;
  --left-right-padding: 28px;
}

.product-upsell__btn-hidden {
  visibility: hidden;
  position: absolute;
  top: 0;
  left: 0;
  font-size: 80%;
  opacity: 0;
  white-space: nowrap;
}

.product-upsell__btn-progress {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  content-visibility: hidden;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.product-upsell__btn-check {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 14px;
  height: 8px;
  border-left: var(--BORDER-WIDTH) solid var(--white);
  border-bottom: var(--BORDER-WIDTH) solid var(--white);
  margin-top: -2px;
  transform: translate(-50%, -50%) rotate(-45deg);
  opacity: 0;
}

.product-upsell__btn.is-success,
.product-upsell__btn.is-success:disabled,
.product-upsell__btn.is-success:disabled:hover {
  --btn-text: var(--SECONDARY-BUTTONS-COLOR-BG);
  --btn-bg: var(--SECONDARY-BUTTONS-COLOR-TEXT);
  --btn-border: var(--SECONDARY-BUTTONS-COLOR-TEXT);
}

.product-upsell__btn.is-loading .svg-loader circle {
  stroke: var(--SECONDARY-BUTTONS-COLOR-ALPHA-50);
}
.product-upsell__btn.is-loading .svg-loader circle ~ circle {
  stroke: var(--SECONDARY-BUTTONS-COLOR-TEXT);
}

.product-upsell__btn.is-loading,
.product-upsell__btn.is-loading:disabled,
.product-upsell__btn.is-loading:disabled:hover,
.product-upsell__btn.btn--secondary.is-loading:hover {
  --btn-text: var(--SECONDARY-BUTTONS-COLOR-TEXT);
  --btn-bg: var(--SECONDARY-BUTTONS-COLOR-BG);
}

.product-upsell__btn.btn--secondary.is-loading:hover, .btn--secondary .product-upsell__btn.is-loading.shopify-payment-button__button--unbranded:hover {
  transition: none;
}
.product-upsell__btn.btn--secondary.is-loading:hover:before, .btn--secondary .product-upsell__btn.is-loading.shopify-payment-button__button--unbranded:hover:before {
  transform-origin: unset;
  transform: scaleY(0);
}

.product-upsell__btn.is-success > .product-upsell__btn-text,
.product-upsell__btn.is-success > .product-upsell__btn-price {
  opacity: 0;
}
.product-upsell__btn.is-success > .product-upsell__btn-check {
  opacity: 1;
  border-left-color: currentcolor;
  border-bottom-color: currentcolor;
}

.product-upsell__btn.is-loading {
  pointer-events: none;
}
.product-upsell__btn.is-loading > .product-upsell__btn-text,
.product-upsell__btn.is-loading > .product-upsell__btn-price,
.product-upsell__btn.is-loading > .product-upsell__btn-check {
  opacity: 0;
}
.product-upsell__btn.is-loading > .product-upsell__btn-progress {
  opacity: 1;
  content-visibility: visible;
}
.product-upsell__btn.is-loading > .product-upsell__btn-progress circle ~ circle {
  animation-play-state: running;
}

.product-upsell__out-of-stock {
  display: none;
  color: var(--disabled-grey-darken);
  margin: 8px 0 0;
  font-size: inherit;
}

.product-upsell__btn.is-hidden {
  display: none;
}

.product-upsell__btn.is-hidden ~ .product-upsell__out-of-stock {
  display: block;
}

.product-upsell__unavailable {
  margin: 0;
  font-size: calc(0.875rem * var(--adjust-body));
  opacity: 0.65;
}

.product-upsell__errors {
  overflow: hidden;
  visibility: hidden;
  position: relative;
  max-height: 0;
  border: var(--BORDER-WIDTH) solid var(--error);
  border-radius: var(--RADIUS-CHECKBOX);
  background-color: var(--error-bg);
  color: var(--error);
  opacity: 0;
  transition: all 0.3s;
}
.product-upsell__errors.is-visible {
  visibility: visible;
  max-height: 100vh;
  margin: 10px 0;
  opacity: 1;
}
.product-upsell__errors .errors {
  padding: 10px 40px 10px 10px;
  margin: 0;
  border: none;
  text-align: left;
}
.product-upsell__errors .errors__close {
  position: absolute;
  top: 4px;
  right: 12px;
  width: 20px;
  height: 20px;
  padding: 5px;
  z-index: 20;
  cursor: pointer;
}
.product-upsell__errors .icon {
  width: 100%;
  height: 100%;
}

/* Cart */
.product-upsell__holder--cart .product-upsell,
.product-upsell__holder--cart .product-upsell__errors.is-visible {
  margin-bottom: 0;
}
.product-upsell__holder--cart .product-upsell__title {
  font-size: calc(0.815rem * var(--adjust-body));
}
.product-upsell__holder--cart .product-upsell__btn,
.product-upsell__holder--cart .product-upsell__variant-title {
  font-size: calc(0.6875rem * var(--adjust-body));
}

/*================ Siblings - PDP ================*/
.siblings {
  --swatch: var(--text);
  --swatch-size: 44px;
  --inner-offset: calc(var(--BORDER-WIDTH) + 2px);
  --swatches-gap: 12px;
  border: 0;
  margin: 0 0 calc(-1 * var(--swatches-gap));
  padding: 0;
  display: flex;
  width: 100%;
  flex-wrap: wrap;
  justify-content: flex-start;
  align-items: center;
  font-size: 0;
}
@media only screen and (max-width: 767px) {
  .siblings {
    --swatches-gap: 8px;
  }
}

.siblings__legend {
  flex: 0 0 100%;
}

.siblings__button {
  position: relative;
  width: var(--swatch-size);
  height: var(--swatch-size);
  min-width: var(--swatch-size);
  display: block;
}
.siblings__button .lazy-image {
  height: 100%;
}

.siblings__swatch {
  margin: 0 var(--swatches-gap) var(--swatches-gap) 0;
  overflow: hidden;
}
.siblings__swatch:last-child {
  margin-right: 0;
}

.siblings__swatch[aria-current=true] {
  cursor: default;
}
.siblings__swatch[aria-current=true] .siblings__button:after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: var(--swatch-size);
  height: var(--swatch-size);
  min-width: var(--swatch-size);
  border: var(--BORDER-WIDTH) solid var(--swatch);
  z-index: 10;
}
.siblings__swatch[aria-current=true] .siblings__button {
  border: var(--inner-offset) solid var(--bg);
}

.siblings__swatch--sold-out img {
  opacity: 0.8;
}
.siblings__swatch--sold-out .siblings__button:before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 2;
  width: var(--BORDER-WIDTH);
  height: 100%;
  border-radius: 0;
  background: var(--text);
  transform: translate(-50%, -50%) rotate(45deg);
}
.siblings__swatch--sold-out[aria-current=true] .siblings__button:before {
  height: calc(100% + 2 * var(--inner-offset));
}

.siblings__swatch--circle img,
.siblings__swatch--circle svg {
  border-radius: 50%;
  overflow: hidden;
}
.siblings__swatch--circle .siblings__button,
.siblings__swatch--circle .siblings__button:after {
  border-radius: 50%;
}

.siblings__swatch--colors {
  --swatch: #CCC;
}
.siblings__swatch--colors .icon-check {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 22px;
  transform: translate(-50%, -50%);
}
.siblings__swatch--colors .siblings__button {
