        .bodycare-bestsellers.bodycare-bestsellers {
  padding: 24px 52px;
  background-color: #FAF9F4;
  font-family: 'Inter', sans-serif;
}
.bodycare-bestsellers .bodycare-bestsellers__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 24px;
}
.bodycare-bestsellers .bodycare-bestsellers__heading {
  color: #6a1a31;
  font-size: clamp(24px, 3vw, 32px);
  margin: 0;
}
.bodycare-bestsellers .bodycare-bestsellers__shop-all {
  color: #6a1a31 !important;
    font-family: 'Inter', sans-serif;
    font-size: 14px;
    text-decoration: Underline !important;
}
.bodycare-bestsellers .bodycare-bestsellers__track {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.bodycare-bestsellers .bodycare-bestsellers__card {
  display: flex;
  flex-direction: column;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__image-wrap {
  position: relative;
  background: #f4ede4;
  aspect-ratio: 720 / 834;
  margin-bottom: 16px;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__image {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__badge {
    position: absolute;
    top: 12px;
    left: 12px;
    background: #a50066;
    color: #FDF6ED;
    font-size: 10px;
    font-weight: 400;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    padding: 3px 6px;
    border-radius: 2px;
    z-index: 1;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__subtitle {
  font-style: italic;
  font-size: 12px;
  margin: 0 0 4px;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__title-link {
  text-decoration: none;
  color: inherit;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__title {
    font-family: 'Inter',sans-serif;
    font-size: 16px;
    font-weight: 600;
    margin: 0 0 4px;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__description {
  font-size: 14px;
  margin: 0 0 16px;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__button {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    background: #6a1a31;
    color: #FAF5EE;
    border: none;
    border-radius: 3px;
    padding: 8px 16px;
    font-size: 12px;
    font-weight: 300;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    cursor: pointer;
    transition: opacity 0.15s ease;
    font-family: 'Inter', sans-serif;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__button:hover:not(:disabled) {
  opacity: 0.88;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__price {
    FONT-WEIGHT: 600;
}
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__button--disabled,
.bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
/* Mobile + tablet: carousel with visible scrollbar */
@media screen and (max-width: 1024px) {
  .bodycare-bestsellers.bodycare-bestsellers {
    padding: 24px 0;
  }
  .bodycare-bestsellers .bodycare-bestsellers__header {
    padding: 0 12px;
  }
  .bodycare-bestsellers .bodycare-bestsellers__track {
    display: flex;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    gap: 16px;
    padding: 0 12px 20px;
    box-sizing: border-box;
    scrollbar-color: #6a1a31 #F0E6D8;
    scrollbar-width: thin;
  }
  .bodycare-bestsellers .bodycare-bestsellers__card {
    flex: 0 0 calc((100% - 16px) / 1.5);
    scroll-snap-align: start;
  }
  .bodycare-bestsellers .bodycare-bestsellers__heading {
    font-size: 28px;
  }
  .bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__badge {
    font-size: 9px;
  }
  .bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__subtitle {
    font-size: 13px;
  }
  .bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__title {
    font-size: 16px;
  }
  .bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__description {
    font-size: 13px;
  }
  .bodycare-bestsellers .bodycare-bestsellers__card .bodycare-bestsellers__button {
    font-size: 12px;
  }
}
      

