/* ===== inline <style> ===== */

        .hn-tc,
.hn-tc * {
  box-sizing: border-box;
}
.hn-tc [hidden] {
  display: none !important;
}
.hn-tc {
  --hn-tc-gutter: 16px;
  --hn-tc-col: 400px;
  --hn-tc-panel-min-h: 150px;
  position: relative;
  width: 100%;
}
.hn-tc .hn-tc__viewport {
  position: relative;
  overflow: hidden;
  width: 100%;
  touch-action: pan-y;
}
.hn-tc .hn-tc__viewport .hn-tc__track {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
  transition: transform 0.45s cubic-bezier(0.22, 0.61, 0.36, 1);
  will-change: transform;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
}
.hn-tc .hn-tc__viewport .hn-tc__track.is-dragging {
  transition: none;
}
.hn-tc .hn-tc__viewport .hn-tc__slide {
  position: relative;
  flex: 0 0 100%;
  min-width: 100%;
  margin: 0;
  padding: 0;
}
.hn-tc .hn-tc__viewport .hn-tc__picture,
.hn-tc .hn-tc__viewport .hn-tc__img {
  display: block;
  width: 100%;
  max-width: none;
  height: auto;
  -webkit-user-drag: none;
  pointer-events: none;
}
/* mobile: centered between the gutters */
.hn-tc .hn-tc__viewport .hn-tc__stage {
  position: absolute;
  z-index: 2;
  left: var(--hn-tc-gutter);
  right: var(--hn-tc-gutter);
  bottom: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}
.hn-tc .hn-tc__viewport .hn-tc__content {
  flex: 0 1 var(--hn-tc-col);
  width: auto;
  max-width: var(--hn-tc-col);
  min-width: 0;
  min-height: var(--hn-tc-panel-min-h);
  text-align: center;
}
.hn-tc .hn-tc__viewport .hn-tc__panel {
  color: #F5E4C8;
  text-align: center;
}
.hn-tc .hn-tc__viewport .hn-tc__badge {
  display: inline-block;
  background: #D1E4F2;
  color: #6A1A31;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 12px;
  margin: 0 0 14px;
}
.hn-tc .hn-tc__viewport .hn-tc__quote {
  font-family: 'CooperBTLight', GowunBatang;
  font-size: 24px;
  line-height: 1.2;
  color: #F5E4C8;
  text-align: center;
  margin: 0 0 26px;
}
.hn-tc .hn-tc__viewport .hn-tc__cta {
  display: inline-block;
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  text-decoration: underline;
  text-underline-offset: 3px;
  color: inherit;
  cursor: pointer;
}
.hn-tc .hn-tc__viewport .hn-tc__dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin: 30px 0 0;
  padding: 0;
  list-style: none;
}
.hn-tc .hn-tc__viewport .hn-tc__dot {
  display: block;
  flex: 0 0 8px;
  width: 8px;
  height: 8px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(245, 228, 200, 0.45);
  cursor: pointer;
  appearance: none;
}
.hn-tc .hn-tc__viewport .hn-tc__dot.is-active {
  background: #F5E4C8;
}
.hn-tc .hn-tc__viewport .hn-tc__arrow {
  display: none;
  flex: 0 0 auto;
  line-height: 0;
  cursor: pointer;
  padding: 6px;
  background: transparent;
  border: 0;
  color: #F5E4C8;
  appearance: none;
}
.hn-tc .hn-tc__viewport .hn-tc__arrow--next {
  transform: scaleX(-1);
}
.hn-tc .hn-tc__viewport .hn-tc__arrow svg {
  display: block;
}
@media (min-width: 750px) {
  .hn-tc {
    --hn-tc-gutter: 32px;
    --hn-tc-col: 400px;
    --hn-tc-panel-min-h: 170px;
  }
  .hn-tc .hn-tc__viewport .hn-tc__stage {
    right: auto;
    bottom: auto;
    top: 50%;
    transform: translateY(-50%);
    justify-content: flex-start;
    gap: 40px;
  }
  .hn-tc .hn-tc__viewport .hn-tc__content {
    flex: 0 0 var(--hn-tc-col);
    width: var(--hn-tc-col);
    max-width: none;
  }
  .hn-tc .hn-tc__viewport .hn-tc__quote {
    font-size: 25px;
  }
  .hn-tc .hn-tc__viewport .hn-tc__arrow {
    display: block;
    padding: 10px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .hn-tc .hn-tc__viewport .hn-tc__track {
    transition: none;
  }
}
      

