.video-section {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 100%;
    align-self: stretch;
    overflow: hidden;
  }

  .video-wrapper {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    z-index: 0;
  }

  .video-player {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    min-width: 100%;
    min-height: 100%;
    width: auto;
    height: auto;
    object-fit: cover;
  }

  .video-link {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 1;
  }

  .video-control {
    position: absolute;
    bottom: 16px;
    right: 16px;
    background: transparent;
    border: none;
    padding: 0;
    cursor: pointer;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2;
  }

  .video-control:focus-visible {
    outline: 2px solid #F7E9D6;
    outline-offset: 2px;
    border-radius: 50%;
  }

  .gpvt-icon-play {
    display: none !important;
  }

  .gpvt-icon-pause {
    display: block !important;
  }

  .video-control.is-paused .gpvt-icon-play {
    display: block !important;
  }

  .video-control.is-paused .gpvt-icon-pause {
    display: none !important;
  }

  @media screen and (max-width: 767px) {
    .video-section {
      height: auto;
      aspect-ratio: 1 / 1;
    }
  }
      

