        .hanni-tv-section {
  font-family: 'Inter', sans-serif;
  width: 100%;
  position: relative;
}
.hanni-tv-section .hanni-tv-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  width: 100%;
  padding: 0;
  gap: 0;
  box-sizing: border-box;
  align-items: stretch;
}
.hanni-tv-section .hanni-tv-card {
  position: relative;
  overflow: hidden;
  cursor: pointer;
  border-radius: 0;
  aspect-ratio: 642 / 860;
  background-color: #FFF;
  margin: 0;
  text-decoration: none;
  width: 100%;
  min-width: 0;
  display: block;
}
.hanni-tv-section .hanni-tv-video,
.hanni-tv-section .hanni-tv-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.hanni-tv-section .hanni-tv-video {
  z-index: 2;
}
.hanni-tv-section .hanni-tv-img {
  z-index: 3;
  opacity: 1;
  transition: opacity 0.45s ease;
}
.hanni-tv-section .hanni-tv-card.hanni-tv-card--playing .hanni-tv-img {
  opacity: 0;
}
.hanni-tv-section .hanni-tv-card::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background: linear-gradient(to top, rgba(0,0,0,0.45) 0%, rgba(0,0,0,0.12) 30%, rgba(0,0,0,0) 55%);
}
.hanni-tv-section .hanni-tv-card-inner {
  position: absolute;
  inset: 0;
  z-index: 6;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  padding: 0;
  pointer-events: none;
}
.hanni-tv-section .hanni-tv-text {
  z-index: 6;
  text-align: center;
  padding: 0 28px 40px;
  width: 100%;
  max-width: 370px;
  box-sizing: border-box;
}
.hanni-tv-section h2.hanni-tv-name {
  font-family: 'CooperBTLight', GowunBatang, serif;
  font-size: 24px;
  font-weight: 300;
  color: #FAF5EE;
  letter-spacing: 0.01em;
  margin: 0 0 6px;
}
.hanni-tv-section .hanni-tv-sub {
  font-size: 16px;
  font-weight: 400;
  color: #FAF5EE;
  margin: 0 0 12px;
}
.hanni-tv-section .hanni-tv-cta {
  display: inline-block;
  font-size: 16px;
  font-weight: 400;
  text-transform: uppercase;
  color: #FAF5EE;
  text-decoration: none;
  border-bottom: 1.5px solid #FAF5EE;
  padding-bottom: 2px;
  pointer-events: all;
}
.hanni-tv-section .hanni-tv-arrow {
  display: none;
}

@media (min-width: 768px) and (max-width: 1024px) {
  .hanni-tv-section .hanni-tv-grid { padding: 0; gap: 0; }
  .hanni-tv-section .hanni-tv-text { padding: 0 20px 20px; }
  .hanni-tv-section h2.hanni-tv-name { font-size: 18px; margin: 0 0 4px; }
  .hanni-tv-section .hanni-tv-sub { font-size: 13px; margin: 0 0 12px; }
  .hanni-tv-section .hanni-tv-cta { font-size: 13px; border-bottom-width: 1px; }
}

